const memo = new Map<number, number>();
function fib(n: number): number {
	if (n < 2) return n;
	const cached = memo.get(n);
	if (cached !== undefined) return cached;
	const value = fib(n - 1) + fib(n - 2);
	memo.set(n, value);
	return value;
}

