const coins = [1, 3, 4];
const dp = new Array(7).fill(Infinity);
dp[0] = 0;
for (let v = 1; v <= 6; v++) {
	for (const c of coins) {
		if (c <= v) dp[v] = Math.min(dp[v], dp[v - c] + 1);
	}
}

